/*
 * The coverage and the ink of pixel (x, y) of the mark drawn `size` pixels
 * square, each from zero to LOGO_FULL. Outside the mark both are zero.
 *
 * Every pixel of the table whose position falls within the pixel asked for is
 * averaged, which is a box filter: at `size` equal to LOGO_EXTENT it is one
 * pixel, at half of it four. When `size` exceeds LOGO_EXTENT the span would be
 * empty, and it is widened to the one pixel beneath, which is enlargement by
 * repetition. The arithmetic is integral throughout, because the kernel draws
 * this and PROJECT_GUIDELINES.md, Section 8, keeps floating point out of it.
 */
static inline void LogoSample(int x, int y, int size, unsigned *covered, unsigned *inked)
{
    int first_x;
    int last_x;
    int first_y;
    int last_y;
    unsigned sum_covered = 0U;
    unsigned sum_inked = 0U;
    unsigned count = 0U;

    *covered = 0U;
    *inked = 0U;

    if ((size <= 0) || (x < 0) || (y < 0) || (x >= size) || (y >= size))
    {
        return;
    }

    first_x = (x * LOGO_EXTENT) / size;
    last_x = ((x + 1) * LOGO_EXTENT) / size;
    first_y = (y * LOGO_EXTENT) / size;
    last_y = ((y + 1) * LOGO_EXTENT) / size;

    if (last_x <= first_x)
    {
        last_x = first_x + 1;
    }

    if (last_y <= first_y)
    {
        last_y = first_y + 1;
    }

    for (int row = first_y; row < last_y; ++row)
    {
        for (int column = first_x; column < last_x; ++column)
        {
            const unsigned byte = LogoCoverage[(row * LOGO_EXTENT) + column];

            sum_covered += byte >> 4;
            sum_inked += byte & 0x0FU;
            ++count;
        }
    }

    /* Rounded to the nearest rather than truncated, so that a pixel wholly
     * covered comes back as LOGO_FULL and not one short of it. */
    *covered = ((sum_covered * LOGO_FULL) + ((count * LOGO_LEVELS) / 2U)) / (count * LOGO_LEVELS);
    *inked = ((sum_inked * LOGO_FULL) + ((count * LOGO_LEVELS) / 2U)) / (count * LOGO_LEVELS);

    if (*inked > *covered)
    {
        *inked = *covered;
    }
}

/*
 * One channel of a pixel of the mark: the ground where nothing covers it, the
 * disc where the mark covers and the ink does not, and the ink — each in its
 * proportion. At no coverage it is exactly the ground, which is what keeps a
 * square of nearly-the-ground from showing about the mark.
 */
static inline unsigned LogoMix(unsigned ground, unsigned disc, unsigned ink, unsigned covered,
                               unsigned inked)
{
    return ((ground * (LOGO_FULL - covered)) + (disc * (covered - inked)) + (ink * inked) +
            (LOGO_FULL / 2U)) /
           LOGO_FULL;
}

/* The same, for three colours packed as the 0x00RRGGBB a program's window
 * takes. */
static inline unsigned LogoMixPacked(unsigned ground, unsigned disc, unsigned ink,
                                     unsigned covered, unsigned inked)
{
    unsigned pixel = 0U;

    for (unsigned shift = 0U; shift <= 16U; shift += 8U)
    {
        pixel |= LogoMix((ground >> shift) & 0xFFU, (disc >> shift) & 0xFFU,
                         (ink >> shift) & 0xFFU, covered, inked)
                 << shift;
    }

    return pixel;
}

